import { createClassNameAllocator } from '@cssxio/compiler';
import type { Plugin } from 'esbuild';
import { Buffer } from 'node:buffer';
import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { basename, dirname, resolve } from 'node:path';

import type { CssxPluginOptions } from '..';
import { assertPluginOptions } from '../core/assert-plugin-options';
import { canonicalPath } from '../core/canonical-path';
import { loadTheme, resolveCssFileName, resolveEsbuildAssetPath } from '../core/options';
import { developmentPluginOptions, effectiveClassNameOptions } from '../core/options';
import { sourceSignature } from '../core/source-signature';
import { stableModuleFileName } from '../core/stable-module-file-name';
import type { CssxSourceModule } from '../native/stylesheet';
import { compileCssxStylesheet, cssWithSourceMapComment } from '../native/stylesheet';
import { withClassNameManifest } from '../native/with-class-name-manifest';
import { compileEsbuildStylesheet } from '../transforms/compile-esbuild-stylesheet';
import { isIgnoredProjectSourcePath } from '../transforms/find-project-source-files';
import { hasCssxStyleData } from '../transforms/module-cssx-data';
import { scanProjectCssxSourceModules } from '../transforms/project-scan';
import { transformCssxModule } from '../transforms/transform';
import type { TransformResult } from '../transforms/transform';
import { loaderFor } from './loader-for';
import type { NextDevelopmentHmrConnection } from './next-development-server';
import { createViteNativeSourceWatcher } from './vite-native-source-watcher';

/** Matches JavaScript and TypeScript source files handled by esbuild. */
const SCRIPT_ID = /\.[cm]?[jt]sx?$/;
/** Maximum unconsumed direct-watcher transforms retained while esbuild rebuilds. */
const MAX_PREPARED_TRANSFORMS = 64;
/** Maximum estimated generated bytes retained in prepared esbuild transforms. */
const MAX_PREPARED_TRANSFORM_BYTES = 16 * 1024 * 1024;

/**
 * Creates the CSSX adapter for esbuild. It enables the metafile, transforms matching source files,
 * then emits CSS after esbuild finishes. With `write: false`, CSS and its source map are added to
 * `outputFiles`; otherwise they are written beside esbuild's configured output.
 *
 * @param options Adapter options.
 * @returns An esbuild plugin.
 */
export default function cssxEsbuild(options: CssxPluginOptions = {}): Plugin {
  assertPluginOptions(options);
  if (options.classNameAllocator && options.className) {
    throw new Error('CSSX classNameAllocator owns naming. Omit className when supplying a custom allocator.');
  }
  /** Candidate data indexed by canonical source path for the current build. */
  const dataById = new Map<string, CssxSourceModule>();
  /** Serial namespace shared by all transformed modules in this esbuild plugin instance. */
  const development = options.mode === 'development';
  const classNameAllocator =
    options.classNameAllocator ??
    createClassNameAllocator(
      development ? { ...options.className, variant: 'random' } : effectiveClassNameOptions(options),
    );
  /** CSS asset written by the previous build, used to remove stale output. */
  let emittedAsset: string | undefined;
  /** CSS source map written by the previous build, used to remove stale output. */
  let emittedMapAsset: string | undefined;
  return {
    name: '@cssxio/unplugin',
    setup(build) {
      const workingDirectory = build.initialOptions.absWorkingDir ?? process.cwd();
      const additionalRoots = options.sourceRoots?.map((path) => resolve(workingDirectory, path));
      const developmentCompilationOptions = developmentPluginOptions(options);
      build.initialOptions.metafile = true;
      let developmentHmr: NextDevelopmentHmrConnection | undefined;
      let developmentRuntimeStartup:
        Promise<typeof import('@cssxio/unplugin/internal/development-runtime') | undefined> | undefined;
      let buildRuns = 0;
      let stylesheetRevision = 0;
      let stylesheetPending: Promise<void> | undefined;
      let publishedStylesheet: string | undefined;
      let latestDevelopmentStylesheet: Awaited<ReturnType<typeof compileCssxStylesheet>> | undefined;
      let latestDevelopmentRevision = -1;
      let latestDevelopmentTheme: string | undefined;
      let nativeSourceWatcher: ReturnType<typeof createViteNativeSourceWatcher> | undefined;
      const cssOnlySignatures = new Map<string, string>();
      const sourceDataSignatures = new WeakMap<CssxSourceModule, string>();
      const preparedResults = new Map<
        string,
        { readonly sourceSignature: string; readonly result: TransformResult; readonly size: number }
      >();
      let preparedResultBytes = 0;
      const removePreparedResult = (id: string) => {
        const previous = preparedResults.get(id);
        if (previous) {
          preparedResultBytes -= previous.size;
          preparedResults.delete(id);
        }
      };
      const cachePreparedResult = (id: string, source: string, result: TransformResult) => {
        const size = (source.length + result.code.length) * 2;
        if (size > MAX_PREPARED_TRANSFORM_BYTES) {
          removePreparedResult(id);
          return;
        }
        removePreparedResult(id);
        while (
          preparedResults.size >= MAX_PREPARED_TRANSFORMS ||
          preparedResultBytes + size > MAX_PREPARED_TRANSFORM_BYTES
        ) {
          const oldestId = preparedResults.keys().next().value;
          /* v8 ignore next -- The size condition only enters this loop while the map is at capacity. */
          if (oldestId === undefined) {
            break;
          }
          removePreparedResult(oldestId);
        }
        preparedResults.set(id, { sourceSignature: sourceSignature(source), result, size });
        preparedResultBytes += size;
      };
      const setTransformedData = (id: string, transformed: TransformResult | null) => {
        if (!transformed) {
          const deleted = dataById.delete(id);
          cssOnlySignatures.delete(id);
          removePreparedResult(id);
          nativeSourceWatcher?.unwatch(id);
          return deleted;
        }
        const data: CssxSourceModule = {
          id,
          candidates: transformed.candidates,
          composites: transformed.composites,
          atomicClasses: transformed.atomicClasses,
          origins: transformed.origins,
        };
        const dataSignature = JSON.stringify([data.candidates, data.composites, data.atomicClasses, data.origins]);
        const previousData = dataById.get(id);
        const changed = previousData === undefined || sourceDataSignatures.get(previousData) !== dataSignature;
        sourceDataSignatures.set(data, dataSignature);
        dataById.set(id, data);
        cssOnlySignatures.set(id, transformed.cssOnlySignature);
        if (hasCssxStyleData({ ...data, rules: [] })) {
          nativeSourceWatcher?.watch(id);
        } else {
          nativeSourceWatcher?.unwatch(id);
        }
        return changed;
      };
      const publishStylesheet = async (stylesheet: Awaited<ReturnType<typeof compileCssxStylesheet>>) => {
        const runtime = await developmentRuntimeStartup;
        if (!runtime || !developmentHmr) {
          return;
        }
        const css = cssWithSourceMapComment(stylesheet, 'generated.css');
        if (css !== publishedStylesheet) {
          await runtime.publishNextDevelopmentStylesheet(developmentHmr, css);
          publishedStylesheet = css;
        }
      };
      const notifyStylesheet = (): Promise<void> => {
        if (!development || buildRuns === 0 || !developmentRuntimeStartup) {
          return Promise.resolve();
        }
        stylesheetRevision++;
        if (!stylesheetPending) {
          stylesheetPending = new Promise<void>((resolveNotification) => setImmediate(resolveNotification))
            .then(async () => {
              let publishedRevision = -1;
              do {
                publishedRevision = stylesheetRevision;
                const theme = await loadTheme(options, workingDirectory);
                const stylesheet = await compileCssxStylesheet(
                  [...dataById.values()],
                  theme,
                  developmentCompilationOptions.layer,
                  options.sourceMap ?? true,
                  options.darkMode,
                  options.preflight,
                );
                latestDevelopmentStylesheet = stylesheet;
                latestDevelopmentRevision = publishedRevision;
                latestDevelopmentTheme = theme;
                await publishStylesheet(stylesheet);
              } while (publishedRevision !== stylesheetRevision);
            })
            .catch((error: unknown) => {
              console.warn(
                `CSSX: esbuild stylesheet update failed: ${error instanceof Error ? error.message : String(error)}`,
              );
            })
            .finally(() => {
              stylesheetPending = undefined;
            });
        }
        return stylesheetPending;
      };
      const updateCssOnlySource = async (id: string) => {
        if (!developmentHmr) {
          return;
        }
        const previousSignature = cssOnlySignatures.get(id);
        if (!previousSignature) {
          return;
        }
        try {
          const source = await readFile(id, 'utf8');
          if (preparedResults.get(id)?.sourceSignature === sourceSignature(source)) {
            return;
          }
          const transformed = await transformEsbuildSource(
            source,
            id,
            workingDirectory,
            options,
            development,
            classNameAllocator,
          );
          if (!transformed || transformed.cssOnlySignature !== previousSignature) {
            removePreparedResult(id);
            return;
          }
          const changed = setTransformedData(id, transformed);
          cachePreparedResult(id, source, transformed);
          if (changed) {
            await notifyStylesheet();
          }
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
            console.warn(
              `CSSX: esbuild stylesheet update failed: ${error instanceof Error ? error.message : String(error)}`,
            );
          }
        }
      };
      if (development) {
        const stylesheetFile = resolve(workingDirectory, '.cssx/esbuild.css');
        nativeSourceWatcher = createViteNativeSourceWatcher(updateCssOnlySource, undefined, 'esbuild watcher');
        developmentRuntimeStartup = import('@cssxio/unplugin/internal/development-runtime').then((runtime) => {
          developmentHmr = runtime.startNextDevelopmentServer(workingDirectory, stylesheetFile);
          return runtime;
        });
        developmentRuntimeStartup = developmentRuntimeStartup.catch((error: unknown) => {
          console.warn(`CSSX: esbuild development runtime failed: ${String(error)}`);
          return undefined;
        });
        build.onDispose(() => {
          void developmentRuntimeStartup?.then((runtime) => runtime?.stopNextDevelopmentServer(workingDirectory));
          nativeSourceWatcher?.close();
          nativeSourceWatcher = undefined;
          preparedResults.clear();
          preparedResultBytes = 0;
          cssOnlySignatures.clear();
          developmentHmr = undefined;
        });
      }
      build.onLoad({ filter: SCRIPT_ID }, async ({ path }) => {
        const developmentRuntime = await developmentRuntimeStartup;
        if (isIgnoredProjectSourcePath(path, additionalRoots)) {
          return undefined;
        }
        const code = await readFile(path, 'utf8');
        const id = await canonicalPath(path);
        const prepared = preparedResults.get(id);
        const usePrepared = development && prepared?.sourceSignature === sourceSignature(code);
        const transformed = usePrepared
          ? prepared.result
          : await transformEsbuildSource(code, path, workingDirectory, options, development, classNameAllocator);
        if (usePrepared) {
          removePreparedResult(id);
        }
        if (!transformed) {
          const changed = development ? setTransformedData(id, null) : dataById.delete(id);
          if (development && changed) {
            await notifyStylesheet();
          }
          return undefined;
        }
        const changed = development ? setTransformedData(id, transformed) : true;
        if (!development) {
          dataById.set(id, {
            id,
            candidates: transformed.candidates,
            composites: transformed.composites,
            atomicClasses: transformed.atomicClasses,
            origins: transformed.origins,
          });
        }
        if (development && buildRuns > 0 && changed && !usePrepared) {
          await notifyStylesheet();
        }
        const contents = developmentHmr
          ? `${transformed.code}\n${developmentRuntime?.nextDevelopmentStylesheetHmr(developmentHmr, options.cssFileName ?? 'cssx.css')}`
          : transformed.code;
        return {
          contents,
          loader: loaderFor(path),
          ...(options.themeFile ? { watchFiles: [resolve(workingDirectory, options.themeFile)] } : {}),
        };
      });
      build.onEnd(async (result) => {
        buildRuns++;
        if (result.errors?.length || !result.metafile) {
          return;
        }
        const liveIds = new Set(
          await Promise.all(
            Object.keys(result.metafile.inputs).map((id) => canonicalPath(resolve(workingDirectory, id))),
          ),
        );
        let removedSource = false;
        for (const id of dataById.keys()) {
          if (!liveIds.has(id)) {
            dataById.delete(id);
            cssOnlySignatures.delete(id);
            removePreparedResult(id);
            nativeSourceWatcher?.unwatch(id);
            removedSource = true;
          }
        }
        if (removedSource) {
          latestDevelopmentRevision = -1;
        }
        let compiled: Awaited<ReturnType<typeof compileCssxStylesheet>>;
        if (development) {
          await stylesheetPending;
          const theme = await loadTheme(options, workingDirectory);
          const canReuse =
            !removedSource &&
            latestDevelopmentStylesheet !== undefined &&
            latestDevelopmentRevision === stylesheetRevision &&
            latestDevelopmentTheme === theme;
          compiled = canReuse
            ? latestDevelopmentStylesheet!
            : await compileCssxStylesheet(
                [...dataById.values()],
                theme,
                developmentCompilationOptions.layer,
                options.sourceMap ?? true,
                options.darkMode,
                options.preflight,
              );
          latestDevelopmentStylesheet = compiled;
          latestDevelopmentRevision = stylesheetRevision;
          latestDevelopmentTheme = theme;
          try {
            await publishStylesheet(compiled);
          } catch (error) {
            console.warn(
              `CSSX: esbuild stylesheet update failed: ${error instanceof Error ? error.message : String(error)}`,
            );
          }
        } else {
          const sourceData =
            options.coordination === 'manifest'
              ? (await scanProjectCssxSourceModules(workingDirectory, options)).map(
                  (module) => [module.id, module] as const,
                )
              : [...dataById];
          compiled = await compileEsbuildStylesheet(sourceData, options);
        }
        const assetPath = resolveEsbuildAssetPath(
          workingDirectory,
          build.initialOptions,
          resolveCssFileName(options.cssFileName ?? 'cssx.css', compiled.css),
        );
        if (!compiled.css) {
          if (emittedAsset) {
            await unlink(emittedAsset).catch(() => undefined);
          }
          if (emittedMapAsset) {
            await unlink(emittedMapAsset).catch(() => undefined);
          }
          emittedAsset = undefined;
          emittedMapAsset = undefined;
          return;
        }
        const css = compiled.map ? `${compiled.css}\n/*# sourceMappingURL=${basename(assetPath)}.map */` : compiled.css;
        const mapPath = `${assetPath}.map`;
        const map = compiled.map ? JSON.stringify({ ...compiled.map, file: basename(assetPath) }) : undefined;
        if (build.initialOptions.write === false) {
          if (!result.outputFiles) {
            return;
          }
          if (result.outputFiles.some((file) => file.path === assetPath)) {
            throw new Error(`CSSX CSS asset collision at "${assetPath}".`);
          }
          result.outputFiles.push({ path: assetPath, contents: Buffer.from(css), hash: '', text: css });
          if (map) {
            result.outputFiles.push({ path: mapPath, contents: Buffer.from(map), hash: '', text: map });
          }
          return;
        }
        await mkdir(dirname(assetPath), { recursive: true });
        await writeFile(assetPath, css);
        if (map) {
          await writeFile(mapPath, map);
        }
        emittedAsset = assetPath;
        emittedMapAsset = map ? mapPath : undefined;
      });
    },
  };
}

/** Transforms one source module with the same naming and manifest settings used by onLoad. */
async function transformEsbuildSource(
  code: string,
  path: string,
  workingDirectory: string,
  options: CssxPluginOptions,
  development: boolean,
  classNameAllocator: ReturnType<typeof createClassNameAllocator>,
): Promise<TransformResult | null> {
  const stable = development || options.stableClassNames || options.naming === 'source';
  const developmentOptions = development ? developmentPluginOptions(options) : undefined;
  const transformOptions = {
    ...(developmentOptions ?? options),
    stableClassNames: stable,
    className: developmentOptions ? developmentOptions.className : effectiveClassNameOptions(options),
    ...(stable ? { stableClassNameFileName: stableModuleFileName(workingDirectory, path, development) } : {}),
    classNameAllocator,
  };
  const compilerOptions = { ...transformOptions };
  delete compilerOptions.coordination;
  delete compilerOptions.manifestPath;
  const transform = (allocator: typeof classNameAllocator) =>
    transformCssxModule(code, path, { ...compilerOptions, classNameAllocator: allocator }, undefined, {
      compileCss: false,
    });
  return !development && options.coordination === 'manifest'
    ? withClassNameManifest(options.manifestPath!, compilerOptions.className!, transform)
    : transform(classNameAllocator);
}
